create table public.registry_provenance_links (id uuid primary key default gen_random_uuid(), original_relationship_id uuid not null unique, source_entity_type text not null, source_slug text not null, source_kind text, source_entity text, source_record_id text, source_staging_record_id uuid, target_entity_type text not null, target_slug text not null, target_media_asset_id uuid references public.registry_media_assets(id) on delete set null, relationship_type text not null, relationship_role text, relationship_status text not null, metadata jsonb not null default '{}'::jsonb, original_created_at timestamptz not null, original_updated_at timestamptz not null, archived_at timestamptz not null default now()); create index registry_provenance_links_source_idx on public.registry_provenance_links (source_entity_type, source_record_id); create index registry_provenance_links_target_media_idx on public.registry_provenance_links (target_media_asset_id) where target_media_asset_id is not null; alter table public.registry_provenance_links enable row level security; revoke all on table public.registry_provenance_links from public, anon, authenticated; grant select on table public.registry_provenance_links to authenticated; grant all on table public.registry_provenance_links to service_role; create policy registry_provenance_links_registry_read on public.registry_provenance_links for select to authenticated using (public.current_user_has_capability('manage_registry') or public.current_user_has_capability('view_registry') or public.current_user_is_administrator()); comment on table public.registry_provenance_links is 'Internal provenance records separated from canonical cultural relationships. Preserves legacy source-to-media history without presenting it as a cultural claim.';;
